import { Section } from "./ui/Section";
import { Card } from "./ui/Card";

type ServiceIcon = (props: { className?: string }) => JSX.Element;

const SERVICES: { title: string; desc: string; icon: ServiceIcon; emergency?: boolean }[] = [
  {
    title: "24/7 Emergency Callouts",
    desc: "Burst pipes, gas smells, no heating or hot water — an engineer dispatched any hour, any day.",
    emergency: true,
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="currentColor" aria-hidden="true">
        <path d="M13 2 3 14h7l-1 8 11-14h-7l0-6Z" />
      </svg>
    ),
  },
  {
    title: "Burst Pipes & Leak Repairs",
    desc: "Fast leak detection and repair to stop water damage in its tracks.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <path d="M8 3v6a4 4 0 0 0 8 0V3M6 3h4M14 3h4" strokeLinecap="round" />
        <path d="M12 13v3M9 19c0-2 1.3-3 3-3s3 1 3 3-1.3 3-3 3-3-1-3-3Z" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    title: "Boiler Repair & Installation",
    desc: "All major makes serviced, repaired and installed by Gas Safe engineers.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <rect x="5" y="3" width="14" height="18" rx="2" />
        <circle cx="12" cy="9" r="2" />
        <path d="M9 15h6M9 18h3" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    title: "Central Heating Systems",
    desc: "System design, installation, power flushing and annual servicing.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <path d="M4 20V9a3 3 0 0 1 3-3h10a3 3 0 0 1 3 3v11M7 20v-4M11 20v-4M15 20v-4M19 20v-4" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    title: "Blocked Drains & Toilets",
    desc: "Rapid clearance for blocked drains, sinks and toilets with minimal mess.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <circle cx="12" cy="12" r="8" />
        <path d="M9 10c0-1.5 1-3 3-3s3 1.5 3 3-1 2-3 3-3 1.5-3 3" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    title: "Bathroom & Kitchen Plumbing",
    desc: "New installs, replacements and repairs for taps, sinks, showers and more.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <path d="M4 12h16M6 12V8a2 2 0 0 1 2-2h2M18 12v6a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-2" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    title: "Radiator Repairs & Balancing",
    desc: "Cold spots, leaks and noisy radiators diagnosed and fixed properly.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <rect x="4" y="6" width="16" height="12" rx="1.5" />
        <path d="M8 6v12M12 6v12M16 6v12" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    title: "Landlord Gas Safety Certificates",
    desc: "CP12 inspections and certification for rental properties across the region.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6l-8-3Z" />
        <path d="m9 12 2 2 4-4" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    title: "Water Tanks & Cylinders",
    desc: "Supply, repair and replacement of cold water tanks and hot water cylinders.",
    icon: (p) => (
      <svg viewBox="0 0 24 24" className={p.className} fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
        <rect x="7" y="3" width="10" height="18" rx="5" />
        <path d="M7 13h10" />
      </svg>
    ),
  },
];

export function Services() {
  return (
    <Section id="services" className="max-w-6xl">
      <div className="mx-auto max-w-2xl text-center">
        <h2 className="text-3xl font-bold tracking-tight text-neutral-900 sm:text-4xl dark:text-white">
          What we do
        </h2>
        <p className="mt-3 text-neutral-600 dark:text-neutral-400">
          From a dripping tap to a full heating system install, our engineers
          handle it — no job too big, no callout too late.
        </p>
      </div>

      <div className="mt-12 grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {SERVICES.map((service) => (
          <Card
            key={service.title}
            className={`dark:border-neutral-800 dark:bg-neutral-900 ${
              service.emergency ? "border-amber-300 bg-amber-50 dark:border-amber-700 dark:bg-amber-950/30" : ""
            }`}
          >
            <div
              className={`inline-flex h-11 w-11 items-center justify-center rounded-lg ${
                service.emergency
                  ? "bg-amber-600 text-white"
                  : "bg-neutral-900 text-amber-500 dark:bg-neutral-800"
